with customer_totals as (select customer_id, max(monthly_fee) - min(monthly_fee) as monthly_fee_range, min(monthly_fee) as min_monthly_fee from subscriptions group by customer_id) select c.id, c.name, c.segment, ct.monthly_fee_range, ct.min_monthly_fee from customers c left join customer_totals ct on c.id = ct.customer_id where ct.min_monthly_fee >= 190 order by min_monthly_fee desc, segment;
